BEGIN TRANSACTION;
CREATE TABLE lead_trades (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    ts              INTEGER NOT NULL,        -- our receive time (unix)
    block_ts        INTEGER,                 -- on-chain timestamp from the event
    wallet          TEXT NOT NULL,
    mint            TEXT NOT NULL,
    side            TEXT NOT NULL,           -- 'buy' | 'sell'
    sol_amount      REAL NOT NULL,
    token_amount    INTEGER NOT NULL,
    spot_price_sol  REAL NOT NULL,
    signature       TEXT
);
CREATE TABLE paper_positions (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    mint              TEXT NOT NULL,
    lead_wallet       TEXT NOT NULL,
    opened_ts         INTEGER NOT NULL,
    entry_price_sol   REAL NOT NULL,
    size_sol          REAL NOT NULL,         -- simulated SOL deployed
    lead_entry_price  REAL,                  -- lead's price when they bought
    status            TEXT NOT NULL,         -- 'open' | 'closed'
    closed_ts         INTEGER,
    exit_price_sol    REAL,
    exit_reason       TEXT,                  -- 'lead_sell' | 'take_profit' | 'stop_loss'
    pnl_sol           REAL,
    pnl_pct           REAL
, peak_price_sol REAL, trough_price_sol REAL);
CREATE TABLE wallet_scores (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    wallet        TEXT NOT NULL,
    harvest_ts    INTEGER NOT NULL,        -- shared timestamp for one rotation run
    realized_sol  REAL NOT NULL,
    win_rate      REAL NOT NULL,
    n_trades      INTEGER NOT NULL,
    n_mints       INTEGER NOT NULL,
    avg_buy_sol   REAL NOT NULL,
    source        TEXT                      -- 'harvest' | 'watchlist'
);
CREATE INDEX idx_lead_wallet ON lead_trades(wallet);
CREATE INDEX idx_pos_status ON paper_positions(status);
CREATE INDEX idx_pos_mint ON paper_positions(mint);
CREATE INDEX idx_scores_wallet ON wallet_scores(wallet, harvest_ts);
DELETE FROM "sqlite_sequence";
COMMIT;
